/* eslint-disable space-in-parens */

import AccessorArray = require( '@stdlib/array/base/accessor' );
import ghadamard = require( './index' );


// TESTS //

// The function returns a collection...
{
	const out = new Float64Array( 16 );

	ghadamard( 'row-major', 4, out, 4 ); // $ExpectType Float64Array
	ghadamard( 'row-major', 4, new AccessorArray( out ), 4 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the function is provided a first argument which is not a valid order...
{
	const out = new Float64Array( 16 );

	ghadamard( 10, 4, out, 4 ); // $ExpectError
	ghadamard( true, 4, out, 4 ); // $ExpectError
	ghadamard( false, 4, out, 4 ); // $ExpectError
	ghadamard( null, 4, out, 4 ); // $ExpectError
	ghadamard( undefined, 4, out, 4 ); // $ExpectError
	ghadamard( [], 4, out, 4 ); // $ExpectError
	ghadamard( {}, 4, out, 4 ); // $ExpectError
	ghadamard( ( x: number ): number => x, 4, out, 4 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const out = new Float64Array( 16 );

	ghadamard( 'row-major', '10', out, 4 ); // $ExpectError
	ghadamard( 'row-major', true, out, 4 ); // $ExpectError
	ghadamard( 'row-major', false, out, 4 ); // $ExpectError
	ghadamard( 'row-major', null, out, 4 ); // $ExpectError
	ghadamard( 'row-major', undefined, out, 4 ); // $ExpectError
	ghadamard( 'row-major', [], out, 4 ); // $ExpectError
	ghadamard( 'row-major', {}, out, 4 ); // $ExpectError
	ghadamard( 'row-major', ( x: number ): number => x, out, 4 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a collection...
{
	ghadamard( 'row-major', 4, 10, 4 ); // $ExpectError
	ghadamard( 'row-major', 4, true, 4 ); // $ExpectError
	ghadamard( 'row-major', 4, false, 4 ); // $ExpectError
	ghadamard( 'row-major', 4, null, 4 ); // $ExpectError
	ghadamard( 'row-major', 4, undefined, 4 ); // $ExpectError
	ghadamard( 'row-major', 4, {}, 4 ); // $ExpectError
	ghadamard( 'row-major', 4, ( x: number ): number => x, 4 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a number...
{
	const out = new Float64Array( 16 );

	ghadamard( 'row-major', 4, out, '10' ); // $ExpectError
	ghadamard( 'row-major', 4, out, true ); // $ExpectError
	ghadamard( 'row-major', 4, out, false ); // $ExpectError
	ghadamard( 'row-major', 4, out, null ); // $ExpectError
	ghadamard( 'row-major', 4, out, undefined ); // $ExpectError
	ghadamard( 'row-major', 4, out, [] ); // $ExpectError
	ghadamard( 'row-major', 4, out, {} ); // $ExpectError
	ghadamard( 'row-major', 4, out, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const out = new Float64Array( 16 );

	ghadamard(); // $ExpectError
	ghadamard( 'row-major' ); // $ExpectError
	ghadamard( 'row-major', 4 ); // $ExpectError
	ghadamard( 'row-major', 4, out ); // $ExpectError
	ghadamard( 'row-major', 4, out, 4, 10 ); // $ExpectError
}

// Attached to the main export is an `ndarray` method which returns a collection...
{
	const out = new Float64Array( 16 );

	ghadamard.ndarray( 4, out, 4, 1, 0 ); // $ExpectType Float64Array
	ghadamard.ndarray( 4, new AccessorArray( out ), 4, 1, 0 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const out = new Float64Array( 16 );

	ghadamard.ndarray( '10', out, 4, 1, 0 ); // $ExpectError
	ghadamard.ndarray( true, out, 4, 1, 0 ); // $ExpectError
	ghadamard.ndarray( false, out, 4, 1, 0 ); // $ExpectError
	ghadamard.ndarray( null, out, 4, 1, 0 ); // $ExpectError
	ghadamard.ndarray( undefined, out, 4, 1, 0 ); // $ExpectError
	ghadamard.ndarray( [], out, 4, 1, 0 ); // $ExpectError
	ghadamard.ndarray( {}, out, 4, 1, 0 ); // $ExpectError
	ghadamard.ndarray( ( x: number ): number => x, out, 4, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a collection...
{
	ghadamard.ndarray( 4, 10, 4, 1, 0 ); // $ExpectError
	ghadamard.ndarray( 4, true, 4, 1, 0 ); // $ExpectError
	ghadamard.ndarray( 4, false, 4, 1, 0 ); // $ExpectError
	ghadamard.ndarray( 4, null, 4, 1, 0 ); // $ExpectError
	ghadamard.ndarray( 4, undefined, 4, 1, 0 ); // $ExpectError
	ghadamard.ndarray( 4, {}, 4, 1, 0 ); // $ExpectError
	ghadamard.ndarray( 4, ( x: number ): number => x, 4, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a number...
{
	const out = new Float64Array( 16 );

	ghadamard.ndarray( 4, out, '10', 1, 0 ); // $ExpectError
	ghadamard.ndarray( 4, out, true, 1, 0 ); // $ExpectError
	ghadamard.ndarray( 4, out, false, 1, 0 ); // $ExpectError
	ghadamard.ndarray( 4, out, null, 1, 0 ); // $ExpectError
	ghadamard.ndarray( 4, out, undefined, 1, 0 ); // $ExpectError
	ghadamard.ndarray( 4, out, [], 1, 0 ); // $ExpectError
	ghadamard.ndarray( 4, out, {}, 1, 0 ); // $ExpectError
	ghadamard.ndarray( 4, out, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	const out = new Float64Array( 16 );

	ghadamard.ndarray( 4, out, 4, '10', 0 ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, true, 0 ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, false, 0 ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, null, 0 ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, undefined, 0 ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, [], 0 ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, {}, 0 ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fifth argument which is not a number...
{
	const out = new Float64Array( 16 );

	ghadamard.ndarray( 4, out, 4, 1, '10' ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, 1, true ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, 1, false ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, 1, null ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, 1, undefined ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, 1, [] ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, 1, {} ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const out = new Float64Array( 16 );

	ghadamard.ndarray(); // $ExpectError
	ghadamard.ndarray( 4 ); // $ExpectError
	ghadamard.ndarray( 4, out ); // $ExpectError
	ghadamard.ndarray( 4, out, 4 ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, 1 ); // $ExpectError
	ghadamard.ndarray( 4, out, 4, 1, 0, 10 ); // $ExpectError
}
